def changeInHeight(matrix, startI, startJ):
   coefficient=.01
   value=0
   value+=matrix[startI+1][startJ]-matrix[startI][startJ]
   value+=matrix[startI-1][startJ]-matrix[startI][startJ]
   value+=matrix[startI][startJ+1]-matrix[startI][startJ]
   value+=matrix[startI][startJ-1]-matrix[startI][startJ]
   return coefficient*value

