def replenish(start, updaterMat):
   annualRain=1.4/36
   area=(1000*50/58)**2
   runoffCoefficient=.664*.7+.15*.036+.3*.6
   a=len(start)
   b=len(start[0])
   for i in range(a):
      for j in range(b):
          if updaterMat[i][j]!=0:
              updaterMat[i][j]+=area*annualRain*(1-runoffCoefficient)
   return updaterMat

